{"Affiliate License-Licensee": [], "Affiliate License-Licensor": [], "Agreement Date": [{"start": 141, "text": "February 15, 2011"}], "Anti-Assignment": [], "Audit Rights": [], "Cap On Liability": [{"start": 86058, "text": "Notwithstanding the provisions of this Section 7(d), the  Remarketing Agent shall not be required to contribute any amount in excess of the total price at which Remarketing Securities distributed in the  Remarketing exceed the amount of any damages which the Remarketing Agent has otherwise paid or become liable to pay by reason of any untrue  or alleged untrue statement or omission or alleged omission."}], "Change Of Control": [], "Competitive Restriction Exception": [], "Covenant Not To Sue": [], "Document Name": [{"start": 97, "text": "AMENDED AND RESTATED REMARKETING AGREEMENT"}], "Effective Date": [], "Exclusivity": [{"start": 6312, "text": "The Company and the Trust (together, the "Issuers") hereby appoint  Barclays as exclusive remarketing agent (the "Remarketing Agent"), and Barclays hereby accepts appointment as Remarketing Agent, for the  purpose of (i) remarketing the Remarketing Securities on behalf of the holders thereof and (ii) performing such other duties as are assigned to the  Remarketing Agent in the Remarketing Procedures, all in accordance with and pursuant to the Remarketing Procedures."}], "Expiration Date": [{"start": 89709, "text": "In addition, the obligations of the Remarketing Agent  hereunder may be terminated by it by notice given to the Company prior to 5:00 p.m. (New York City time) on the date immediately preceding the  Commencement Date if, prior to that time, any of the events described in Sections 6(i), (j) or (k) shall have occurred."}, {"start": 89354, "text": "This Agreement shall terminate (i) the Business Day immediately following the Remarketing Settlement Date, (ii) at 5:00  p.m., New York City time, on the last date of the Remarketing if the Remarketing is not successful or (iii) on the effective date of the resignation or  removal of the Remarketing Agent and the appointment of a new Remarketing Agent."}], "Governing Law": [{"start": 94171, "text": "This Agreement shall be governed by, and construed in accordance with, the laws of the State of New York."}], "Insurance": [{"start": 44953, "text": "All such  insurance is outstanding and duly in force on the date hereof and will be outstanding and duly in force on the Commencement Date and the  Remarketing Settlement Date."}, {"start": 44399, "text": "The Company and each of its subsidiaries maintains insurance covering their properties, personnel and business."}, {"start": 44511, "text": "Such insurance insures  against such losses and risks as are adequate in accordance with the Company's perception of customary industry practice to protect the  Company and its subsidiaries and their businesses."}], "Ip Ownership Assignment": [], "Irrevocable Or Perpetual License": [], "Joint Ip Ownership": [], "License Grant": [], "Liquidated Damages": [], "Minimum Commitment": [{"start": 7245, "text": "On the third Business Day immediately preceding the Remarketing Settlement Date (the "Remarketing Date"), the Remarketing Agent shall use  its commercially reasonable efforts to remarket the Remarketing Securities, at a price at least equal to:

(i) 100% of the aggregate Accreted Value thereof as of the end of the day on the day next preceding the Remarketing Settlement Date; or

(ii) on the Maturity Remarketing Date, 100% of the stated liquidation amount of the Preferred Securities or the principal amount at maturity of  the Debentures, as the case may be."}], "Most Favored Nation": [], "No-Solicit Of Customers": [], "No-Solicit Of Employees": [], "Non-Compete": [], "Non-Disparagement": [], "Non-Transferable License": [], "Notice Period To Terminate Renewal": [], "Parties": [{"start": 160, "text": "Barclays"}, {"start": 6289, "text": "Remarketing Agent"}, {"start": 334, "text": "RGA Capital Trust I"}, {"start": 319, "text": "Company"}, {"start": 346, "text": "Trust"}, {"start": 160, "text": "Barclays Capital Inc."}, {"start": 246, "text": "Reinsurance Group of America, Incorporated"}, {"start": 6339, "text": "together, the "Issuers""}], "Post-Termination Services": [], "Price Restrictions": [], "Renewal Term": [], "Revenue/Profit Sharing": [{"start": 55647, "text": "If there has been a successful Remarketing, the Company shall pay to the Remarketing Agent for the  performance of its services as Remarketing Agent hereunder on the Remarketing Settlement Date, by wire transfer to an account designated by the  Remarketing Agent, a fee in an amount equal to 25 basis points (0.25%) of the Accreted Value of the Remarketed Securities."}], "Rofr/Rofo/Rofn": [], "Source Code Escrow": [], "Termination For Convenience": [], "Third Party Beneficiary": [{"start": 92455, "text": "This Agreement and the terms and provisions hereof are for the sole benefit of only those  persons, except that (A) the representations, warranties, indemnities and agreements of the Issuers contained in this Agreement shall also be  deemed to be for the benefit of the officers, directors and employees of the Remarketing Agent and the person or persons, if any, who control the  Remarketing Agent within the meaning of Section 15 of the Securities Act; and (B) any indemnity agreement of the Remarketing Agent contained  in this Agreement shall be deemed to be for the benefit of directors, trustees, officers and employees of the Company, and the Trust, and any  person controlling the Company or the Trust within the meaning of Section 15 of the Securities Act."}], "Uncapped Liability": [], "Unlimited/All-You-Can-Eat-License": [], "Volume Restriction": [], "Warranty Duration": []}

