{"Affiliate License-Licensee": [], "Affiliate License-Licensor": [], "Agreement Date": [{"start": 149, "text": "18th day of May, 2001"}], "Anti-Assignment": [], "Audit Rights": [{"start": 33571, "text": "During reasonable business hours IMPCO and MIL/MINDA will have the right to inspect, and make copies of any and all of the JVC 's business records, including but not limited to financial records, books, accounts and reports. In exercising such right IMPCO and MIL/MINDA will be reasonable."}, {"start": 33888, "text": "During reasonable business hours IMPCO and MIL/MINDA will have the right to visit, enter and inspect each plant and other establishment at which the JVC manufactures and/or processes the Products. In exercising such right, the Parties will be reasonable."}], "Cap On Liability": [], "Change Of Control": [], "Competitive Restriction Exception": [], "Covenant Not To Sue": [], "Document Name": [{"start": 16, "text": "JOINT VENTURE AGREEMENT"}], "Effective Date": [{"start": 41364, "text": "This Agreement shall become effective on the date of execution and shall continue in force and effect for an indefinite term thereafter unless terminated pursuant to the provisions of Article 16 or by all the Parties in writing."}], "Exclusivity": [{"start": 36311, "text": "IMPCO expressly agrees that during the existence of this Agreement, IMPCO shall not enter into any other Joint Venture Agreement or Marketing/Distribution Agreement, with any company or person(s) in the Territory with respect to the Products."}], "Expiration Date": [{"start": 41364, "text": "This Agreement shall become effective on the date of execution and shall continue in force and effect for an indefinite term thereafter unless terminated pursuant to the provisions of Article 16 or by all the Parties in writing."}], "Governing Law": [{"start": 57855, "text": "his Agreement shall be governed by and construed in accordance with the laws of India and the Delhi Courts shall have exclusive jurisdiction over any legal proceedings in respect of this Agreement."}], "Insurance": [], "Ip Ownership Assignment": [], "Irrevocable Or Perpetual License": [], "Joint Ip Ownership": [], "License Grant": [], "Liquidated Damages": [], "Minimum Commitment": [{"start": 42259, "text": "If the JVC fails to sell [one million dollars (US$ 1,000,000.00)] worth of Products in the Territory within [eighteen (18)] months from the date of execution of this Agreement, both the Parties will mutually discuss whether to continue or terminate the Agreement."}], "Most Favored Nation": [], "No-Solicit Of Customers": [], "No-Solicit Of Employees": [], "Non-Compete": [{"start": 36563, "text": "MINDA/MIL, since it will have access to the Technical Know-How which it would not have had otherwise, expressly agree that:



