{"Affiliate License-Licensee": [], "Affiliate License-Licensor": [], "Agreement Date": [{"start": 122, "text": "June 11, 2015,"}], "Anti-Assignment": [{"start": 49709, "text": "This Agreement shall be binding upon and inure to the benefit of the Parties and their successors and permitted assigns; provided, however, that the rights and obligations of any Party under this Agreement shall not be assignable by such Party without the prior written consent of the"}, {"start": 36572, "text": "Neither Party may assign its rights under this Agreement without prior written consent from the other Party, which consent shall not be unreasonably withheld; provided, however, that either Party may assign its rights under this Agreement to a successor in interest resulting from any merger, reorganization, consolidation or as part of a sale of all or substantially all of its assets."}, {"start": 50003, "text": "other Party pursuant to Section 8.1."}], "Audit Rights": [], "Cap On Liability": [{"start": 39023, "text": "Except as otherwise provided in Section 10.5, in the event of any breach of a term or condition of this Agreement by either Party, the other Party's remedy shall be limited to the direct damages caused thereby and in no event shall a Party be liable to the other Party for any consequential, indirect, pecuniary, punitive, or economic damages, howsoever caused."}], "Change Of Control": [], "Competitive Restriction Exception": [], "Covenant Not To Sue": [], "Document Name": [{"start": 54, "text": "TRANSPORTATION SERVICES AGREEMENT"}], "Effective Date": [{"start": 122, "text": "June 11, 2015"}], "Exclusivity": [], "Expiration Date": [{"start": 11876, "text": "The Agreement shall continue through the project's in-service date and for a period of fifteen (15) years after the project's in-service date ("Initial Term")."}], "Governing Law": [{"start": 46058, "text": "This Agreement shall be construed and interpreted in accordance with the laws of the State of Ohio, without recourse to any principles of law governing conflicts of law, which might otherwise be applicable."}], "Insurance": [], "Ip Ownership Assignment": [], "Irrevocable Or Perpetual License": [], "Joint Ip Ownership": [], "License Grant": [], "Liquidated Damages": [{"start": 41073, "text": "If Shipper fails to notify MPL within one hundred and eighty (180) days of the Project's in-service date or if MPL is unsuccessful in obtaining additional volume commitments as provided for in Section 3.8 to"}, {"start": 41290, "text": "fully replace Shipper's original volume commitment as submitted in its Capacity Request Form in Exhibit C, Shipper will reimburse MPL for Shipper's pro rata portion of actual and committed Construction Costs, plus, an administrative fee of ten (10) percent of said costs (such reimbursement is hereinafter referred to as the "Construction Cost Reimbursement")."}, {"start": 41651, "text": "The Parties agree that the Construction Cost Reimbursement shall be deemed liquidated damages and that such amount shall not be deemed a penalty, but rather represents a reasonable amount of liquidated damages in light of the anticipated or actual harm caused by Shipper's termination of this Agreement as stated, the difficulties of proof of loss, and the inconvenience or non- feasibility of otherwise obtaining an adequate remedy, and that the payment of such amount shall be MPL's sole and exclusive remedy for such termination by Shipper."}], "Minimum Commitment": [{"start": 15655, "text": "Subject to the provisions of Section 5 of this Agreement, if the volume of each Product shipped by Shipper on the Pipeline during the Quarter is less than the applicable Quarterly Volume Commitment for that Product then, in addition to paying any amounts incurred by Shipper pursuant to Section 3.4 with respect to Shipper Deliveries for such Quarter, Shipper shall also pay MPL a deficiency payment (the "Quarterly Deficiency Payment"); equal to the product of:

(a) the difference between the applicable Quarterly Volume Commitment for that Product for such Quarter and the volume of Shipper Deliveries of that Product on the Pipeline for such Quarter (the "Deficiency Volume"); and

(b) the applicable Tariff Rate for that Product for such Quarter."}, {"start": 21830, "text": "If Shipper makes a Pre-Service Increase Request, MPL shall notify Shipper of its new Quarterly Volume Commitment within thirty (30) days following receipt of Shipper's Pre-Service Increase Request, and Exhibit C shall be deemed revised to reflect Shipper's new volume commitment, which shall equal the sum of its original Capacity Request Form volume commitment and its Pre-Service Increase Request or its allocated portion thereof pursuant to this Section 3.9."}, {"start": 13490, "text": "Shipper guarantees that during each Contract Year, Shipper will meet its Quarterly Volume Commitment or, in the event it fails to do so, shall remit to MPL the Quarterly Deficiency Payment pursuant to Section 3.5."}], "Most Favored Nation": [{"start": 39391, "text": "Upon termination of this Agreement for reasons other than a default by Shipper, pursuant to any provisions of this Agreement or any other termination of this Agreement initiated by Shipper pursuant to Section 5, Shipper shall have the right to require MPL to enter into a new transportation service agreement with Shipper that (a) is consistent with the terms and objectives set forth in this Agreement and (b) has commercial terms that are, in the aggregate, equal to or more favorable to Shipper than fair market value terms as would be agreed by similarly-situated parties negotiating at arm's length provided."}], "No-Solicit Of Customers": [], "No-Solicit Of Employees": [], "Non-Compete": [], "Non-Disparagement": [], "Non-Transferable License": [], "Notice Period To Terminate Renewal": [{"start": 12647, "text": "This Agreement will automatically renew for up to two (2) renewal terms of five (5) years each (each, an "Extension Period") unless either Party provides the other Party with written notice of its intent to terminate this Agreement at least six (6) months prior to the end of the Initial Term or the then current Extension Period."}], "Parties": [{"start": 152, "text": "Marathon Petroleum Company LP"}, {"start": 184, "text": "Shipper"}, {"start": 261, "text": "MPL"}, {"start": 198, "text": "Marathon Pipe Line LLC"}, {"start": 268, "text": "both referred to jointly as the "Parties" and each individually as a "Party"."}], "Post-Termination Services": [], "Price Restrictions": [], "Renewal Term": [{"start": 12647, "text": "This Agreement will automatically renew for up to two (2) renewal terms of five (5) years each (each, an "Extension Period") unless either Party provides the other Party with written notice of its intent to terminate this Agreement at least six (6) months prior to the end of the Initial Term or the then current Extension Period."}], "Revenue/Profit Sharing": [], "Rofr/Rofo/Rofn": [{"start": 31795, "text": "To the extent permitted by Governmental Authorities, MPL will provide to each Shipper a first right, on terms and conditions specified by MPL that is consistent with this first right, to submit a binding nomination to ship, or otherwise pay for, a committed volume of Product on the expansion capacity ("Requested Expansion Volume Commitment")."}, {"start": 32306, "text": "No later than sixty (60) days following the date of MPL's Expansion Notice, Shipper must commit to, in a form acceptable to MPL in MPL's sole discretion, its Requested Expansion Volume Commitment ("Election Deadline")."}, {"start": 32525, "text": "In the event that, pursuant to this first right, MPL receives binding commitments for volumes that exceed the expansion capacity available for committed volumes, each Shipper that submitted a binding commitment pursuant to this first right procedure shall be allocated the lesser of: (i) its Requested Expansion Volume Commitment, or (ii) the Shipper's pro-rata share of the expansion capacity available for committed volumes, which shall be calculated by multiplying (1) the Shipper's Proportionate Share, times (2) the expansion capacity available for committed volumes ("Expansion Volume Commitment")."}], "Source Code Escrow": [], "Termination For Convenience": [{"start": 40575, "text": "If MPL is in compliance with the terms and conditions of this Agreement, and Shipper decides to terminate this Agreement after the Effective Date but prior to the commencement of transportation service on the Pipeline, Shipper shall notify MPL of its decision to terminate within one hundred and eighty (180) days of the Project's in-service date to allow MPL the opportunity to provide Shipper's unwanted capacity to other interested shippers as Unsubscribed Capacity as set forth in Section 3.8."}], "Third Party Beneficiary": [], "Uncapped Liability": [{"start": 39023, "text": "Except as otherwise provided in Section 10.5, in the event of any breach of a term or condition of this Agreement by either Party, the other Party's remedy shall be limited to the direct damages caused thereby and in no event shall a Party be liable to the other Party for any consequential, indirect, pecuniary, punitive, or economic damages, howsoever caused."}], "Unlimited/All-You-Can-Eat-License": [], "Volume Restriction": [{"start": 32140, "text": "The amount of expansion capacity available for volume commitments pursuant to this Section 6.6 shall not exceed ninety percent (90%) of the total expansion capacity."}, {"start": 17210, "text": "If, during any Quarter of the Contract Year, Shipper deliveries on the Pipeline exceed the applicable Quarterly Volume Commitment requirements, Shipper shall be permitted to apply Prepaid Transportation Credits against any amount due from Shipper and payable to MPL with respect to the transportation of volumes on the Pipeline for such Quarter."}], "Warranty Duration": []}

